from functools import cache

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_up_to(n: int) -> int:
            if n < 1:
                return 0

            digits = list(map(int, str(n)))
            L = len(digits)

            @cache
            def dp(pos: int, cur_sum: int, cur_prod: int, tight: bool, started: bool) -> int:
                if pos == L:
                    if not started:
                        return 0
                    return 1 if cur_prod % cur_sum == 0 else 0

                limit = digits[pos] if tight else 9
                ans = 0
                for d in range(limit + 1):
                    next_tight = tight and (d == limit)
                    if not started and d == 0:
                        ans += dp(pos + 1, 0, 1, next_tight, False)
                    else:
                        ans += dp(pos + 1, cur_sum + d, cur_prod * d, next_tight, True)
                return ans

            result = dp(0, 0, 1, True, False)
            dp.cache_clear()
            return result

        return count_up_to(r) - count_up_to(l - 1)
